Here’s a small, dependency-free Python app. Sign-ups are stored server-side in SQLite; visitors cannot retrieve participant details. A unique email constraint prevents duplicate bookings, and `BEGIN IMMEDIATE` makes the capacity check and insertion atomic.

Save as `app.py`:

```python
import json
import re
import sqlite3
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

DB = "workshop.db"
CAPACITY = 20

PAGE = """<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Workshop sign-up</title>
</head>
<body>
  <main>
    <h1>Workshop sign-up</h1>
    <p>There are 20 seats available.</p>
    <form id="signup">
      <p><label>Name <input name="name" required maxlength="200"></label></p>
      <p><label>Email <input name="email" type="email" required maxlength="254"></label></p>
      <button>Reserve a seat</button>
    </form>
    <p id="message" role="status"></p>
  </main>
  <script>
    const form = document.querySelector('#signup');
    const message = document.querySelector('#message');
    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      const button = form.querySelector('button');
      button.disabled = true;
      message.textContent = 'Booking…';
      try {
        const response = await fetch('/signup', {
          method: 'POST',
          headers: {'Content-Type': 'application/json'},
          body: JSON.stringify(Object.fromEntries(new FormData(form)))
        });
        const result = await response.json();
        message.textContent = result.message;
        if (response.ok) form.reset();
      } catch {
        message.textContent = 'Unable to connect. Please try again.';
      } finally {
        button.disabled = false;
      }
    });
  </script>
</body>
</html>
"""

def initialize():
    with sqlite3.connect(DB) as db:
        db.execute("""
            CREATE TABLE IF NOT EXISTS participants (
                id INTEGER PRIMARY KEY,
                name TEXT NOT NULL,
                email TEXT NOT NULL UNIQUE
            )
        """)

def book(name, email):
    db = sqlite3.connect(DB, timeout=10)
    try:
        # Acquires the write lock before checking either condition.
        db.execute("BEGIN IMMEDIATE")
        if db.execute(
            "SELECT 1 FROM participants WHERE email = ?", (email,)
        ).fetchone():
            db.rollback()
            return 409, "This email has already booked a seat."

        count = db.execute("SELECT COUNT(*) FROM participants").fetchone()[0]
        if count >= CAPACITY:
            db.rollback()
            return 409, "Sorry, the workshop is full."

        db.execute(
            "INSERT INTO participants (name, email) VALUES (?, ?)",
            (name, email),
        )
        db.commit()
        return 201, "Your seat is reserved!"
    except Exception:
        db.rollback()
        raise
    finally:
        db.close()

class Handler(BaseHTTPRequestHandler):
    def send_content(self, status, content, content_type):
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(content)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(content)

    def send_json(self, status, message):
        content = json.dumps({"message": message}).encode("utf-8")
        self.send_content(status, content, "application/json; charset=utf-8")

    def do_GET(self):
        if self.path != "/":
            self.send_error(404)
            return
        self.send_content(200, PAGE.encode("utf-8"), "text/html; charset=utf-8")

    def do_POST(self):
        if self.path != "/signup":
            self.send_error(404)
            return

        try:
            length = int(self.headers.get("Content-Length", "0"))
            if not 0 < length <= 4096:
                raise ValueError()
            data = json.loads(self.rfile.read(length))
            name = data["name"].strip()
            email = data["email"].strip().casefold()
            if (
                not name or len(name) > 200 or len(email) > 254
                or not re.fullmatch(r"[^\\s@]+@[^\\s@]+\\.[^\\s@]+", email)
            ):
                raise ValueError()
        except (ValueError, TypeError, KeyError, AttributeError):
            self.send_json(400, "Please enter a valid name and email.")
            return

        try:
            status, message = book(name, email)
        except sqlite3.Error:
            self.send_json(503, "Booking is temporarily unavailable. Please try again.")
            return
        self.send_json(status, message)

if __name__ == "__main__":
    initialize()
    print("Open http://localhost:8000")
    ThreadingHTTPServer(("127.0.0.1", 8000), Handler).serve_forever()
```

Run with `python3 app.py`, then open `http://localhost:8000`.

For deployment, use HTTPS and protect the SQLite file and its backups from public access. The app binds to localhost by default; a production reverse proxy can forward requests to it.

